      const template = readFileSync(resolve(outDir, "index.html"), "utf8");
      const fallback = (template.match(/<meta name="description" content="([^"]*)"/)?.[1] ?? "").replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
      const all = pages(fallback);
